CREATE TRIGGER trg_gate_boundary_config_audit
  AFTER UPDATE ON public.gate_boundary_config
  FOR EACH ROW EXECUTE FUNCTION public.fn_gate_boundary_config_audit_trigger();

DECLARE
  v_gate_type TEXT;
  v_review_mode TEXT;
BEGIN
  SELECT sc.gate_type, sc.review_mode
    INTO v_gate_type, v_review_mode
    FROM public.venture_stages sc
   WHERE sc.stage_number = p_stage_number
   LIMIT 1;

  IF NOT FOUND THEN
    -- Non-existent stage: single row, NULLs, creates_decision=false.
    RETURN QUERY SELECT FALSE, NULL::TEXT, NULL::TEXT;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    (v_gate_type IN ('kill','promotion') OR v_review_mode = 'review'),
    v_gate_type,
    v_review_mode;
END;

